def gerar_notas():
    for slug, (title, content) in PAGES.items():
        page = f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · ETAL Connect</title><link rel="stylesheet" href="assets/documentacao.css"></head><body class="note-page"><header class="toolbar"><a href="../DOCUMENTACAO.html" class="btn">← Documentação visual</a><a href="../index.html" class="btn">Abrir app ↗</a></header><main class="notes"><div class="eyebrow">ETAL Connect / notas de continuidade</div><h1>{escape(title)}</h1>{content}<footer class="caption" style="margin-top:40px;border-top:1px solid var(--line);padding-top:20px">Registro da implementação · novembro de 2026. Não constitui documentação oficial do IFRN, SUAP, NADIC ou do evento.</footer></main></body></html>'''
        (ROOT / 'docs' / f'{slug}.html').write_text(page)
    module = runpy.run_path(str(ROOT / 'scripts/build-documentacao.py'))
    (ROOT / 'docs/tecnico.html').write_text('''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estrutura e execução · ETAL Connect</title><link rel="stylesheet" href="assets/documentacao.css"></head><body class="note-page"><header class="toolbar"><a href="../DOCUMENTACAO.html" class="btn">← Documentação visual</a></header><main class="notes"><div class="eyebrow">Consulta técnica</div><div class="reference-body">''' + module['markdown']((ROOT / 'docs/tecnico/04-arquitetura.md').read_text()).replace('<h1>', '<h2>').replace('</h1>', '</h2>') + '</div></main></body></html>')
    module['gerar']()


if __name__ == '__main__':
    gerar_notas()
